import fs from 'node:fs';
import path from 'node:path';
import { hero, brand as person, flipboard, cta } from '@/lib/content';

// the sticker-collage aspirant: generated by scripts/gen-aspirant.mjs, inlined at build time
const art = (f: string) => fs.readFileSync(path.join(process.cwd(), 'lib', 'art', f), 'utf8');
const ASPIRANT = art('aspirant-figure.svg') + art('aspirant-stickers.svg');

const Spec = ({ t, below }: { t: string; below?: boolean }) => (
  <span className={below ? 'spec spec--below' : 'spec'}>{t}</span>
);

// [left %, top %, size px, delay s, glyph]
const SPARKLES: [number, number, number, number, string][] = [
  [8, 6, 18, 0, '✦'],
  [27, 46, 14, 1.2, '♡'],
  [44, 30, 22, 0.5, '✦'],
  [58, 52, 12, 2.1, '✧'],
  [66, 34, 16, 1.6, '✦'],
  [79, 44, 20, 0.9, '♡'],
  [91, 30, 14, 2.6, '✧'],
  [36, 62, 16, 3.0, '✦'],
  [72, 66, 12, 0.3, '✧'],
];

function Chars({ word }: { word: string }) {
  return (
    <span className="hx__w">
      {word.split('').map((c, i) => (
        <span className="hx__ch" aria-hidden="true" key={i} style={{ position: 'relative', display: 'inline-block' }}>
          {c}
        </span>
      ))}
    </span>
  );
}

const ArrowIcon = () => (
  <svg viewBox="0 0 16 16" aria-hidden="true">
    <path d="M3 8h9.5M8.5 4l4 4-4 4" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);
const TestIcon = () => (
  <svg viewBox="0 0 16 16" aria-hidden="true">
    <rect x="3" y="2" width="10" height="12.5" rx="2" fill="none" stroke="currentColor" strokeWidth="1.4" />
    <path d="M5.6 6.2l1.2 1.2 2.4-2.4M5.6 10.4h4.8" fill="none" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* Blueprint x-ray, drawn in the cut-out's own pixel coordinates (289×695).
   Animated with CSS (see .xr-* in additions.css): breathing ribs, a beating heart,
   a slow head nod, a swaying arm, a scan beam and twinkles. */
const DOUBLE = (d: string, w: number) => (
  <>
    <path className="xr__o" d={d} style={{ strokeWidth: w }} />
    <path className="xr__i" d={d} style={{ strokeWidth: w * 0.46 }} />
  </>
);
const pivot = (x: number, y: number) => ({ transformOrigin: `${x}px ${y}px` });

function XRay() {
  const teeth = Array.from({ length: 7 }, (_, i) => 95 + i * 3.4);
  const spine = Array.from({ length: 15 }, (_, i) => ({ x: 112 + i * 0.75, y: 122 + i * 17, w: 7 + Math.min(i, 10) * 0.45 }));
  const ribs = Array.from({ length: 7 }, (_, i) => 160 + i * 15);
  const sparkles: [number, number, number][] = [[60, 30, 0], [150, 14, 0.8], [70, 128, 1.6], [214, 120, 2.2], [40, 260, 1.1], [236, 300, 2.8]];
  return (
    <div className="hx__line xr xr--body" aria-hidden="true">
      <span className="xr__silw">
        <span className="xr__sil" />
      </span>
      <svg className="xr__svg" viewBox={`0 0 ${person.cutoutW} ${person.cutoutH}`} aria-hidden="true">
        <defs>
          <linearGradient id="xr-scan" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#ff4f9a" stopOpacity="0" />
            <stop offset=".7" stopColor="#ff4f9a" stopOpacity=".22" />
            <stop offset="1" stopColor="#ff4f9a" stopOpacity=".55" />
          </linearGradient>
          <radialGradient id="xr-heart" cx=".4" cy=".35" r=".7">
            <stop offset="0" stopColor="#ffd0e6" />
            <stop offset=".55" stopColor="#ff6fae" />
            <stop offset="1" stopColor="#e0428f" />
          </radialGradient>
        </defs>

        {/* spine */}
        {spine.map((v, i) => (
          <g key={i} transform={`translate(${v.x} ${v.y})`}>
            {DOUBLE(`M${-v.w - 5} 0H${v.w + 5}`, 3.2)}
            <rect className="xr__b" x={-v.w / 2 - 2} y="-5.5" width={v.w + 4} height="11" rx="3.5" />
            <path className="xr__ln" d={`M0 -2.5V2.5`} />
          </g>
        ))}

        {/* shoulder blades, behind the ribs */}
        <path className="xr__scap" d="M58 170C70 166 88 172 92 186C94 204 86 226 76 240C68 236 60 222 56 206C54 192 54 178 58 170Z" />
        <path className="xr__scap" d="M150 166C162 160 180 164 186 176C186 196 178 220 168 234C160 228 152 212 150 196C148 184 148 174 150 166Z" />

        {/* ribcage (breathes) */}
        <g className="xr-ribs" style={pivot(116, 158)}>
          <path className="xr__b" d="M110 150L122 150L121 224L111 224Z" />
          <path className="xr__ln" d="M110 168H122M110 186H122M110 204H122" />
          {ribs.map((y, i) => {
            const k = 1 - i * 0.06;
            return (
              <g key={y}>
                {DOUBLE(`M114 ${y}C${92 * k + 8} ${y - 3} ${66 + i * 2} ${y + 6} ${64 + i * 3} ${y + 24}`, 4.4)}
                {DOUBLE(`M119 ${y}C${144 - i} ${y - 5} ${168 - i * 2} ${y + 3} ${172 - i * 3} ${y + 22}`, 4.4)}
              </g>
            );
          })}
          {/* the heart */}
          <g className="xr-heart" style={pivot(103, 206)}>
            <path d="M103 216C92 208 86 202 86 195C86 189 91 185 96 186C99 186 102 188 103 191C104 188 107 186 110 186C115 185 120 189 120 195C120 202 114 208 103 216Z" fill="url(#xr-heart)" stroke="#e0428f" strokeWidth="1.2" />
            <path d="M93 192C94 190 96 189 98 189" fill="none" stroke="#fff" strokeWidth="1.4" strokeLinecap="round" opacity=".8" />
          </g>
        </g>

        {/* collarbones + shoulder joints */}
        {DOUBLE('M112 148C95 146 75 152 52 162', 6.5)}
        {DOUBLE('M118 148C140 143 164 145 186 152', 6.5)}
        <circle className="xr__b xr__joint" cx="50" cy="170" r="9.5" />
        <circle className="xr__b xr__joint" cx="190" cy="158" r="9.5" />

        {/* head (nods a little) */}
        <g className="xr-head" style={pivot(110, 120)}>
          <path className="xr__b xr__skull" d="M74 74C70 40 86 18 106 18C128 18 140 38 138 66C137 82 132 94 126 102C122 110 114 116 106 116C96 116 88 110 84 102C78 96 75 86 74 74Z" />
          <path className="xr__brain" d="M78 60C78 36 92 22 107 22C125 22 136 38 134 58C124 54 116 56 108 54C98 52 88 56 78 60Z" />
          <g className="xr__gyri xr-flow">
            <path d="M90 34C94 38 90 44 95 48" />
            <path d="M104 26C102 32 108 36 104 42C101 46 106 50 104 54" />
            <path d="M118 28C116 34 122 38 119 44C117 48 122 52 120 55" />
            <path d="M84 52C90 48 96 52 102 49C108 46 114 50 120 47C126 45 130 49 133 50" />
            <path d="M128 36C126 42 131 45 129 51" />
            <path d="M96 30C99 27 103 28 106 26" />
          </g>
          <ellipse className="xr__eye" cx="95" cy="72" rx="8" ry="6.5" />
          <ellipse className="xr__eye" cx="118" cy="72" rx="7" ry="6.5" />
          <path className="xr__lash" d="M88 66l-3 -3M92 64.5l-1.5 -3.5M97 64l0 -3.6M112 64.5l-1 -3.4M116 64l.6 -3.6M121 64.6l2 -3.2" />
          <path className="xr__b" d="M106 76C103 81 102 86 104 88C105 89 108 89 109 88C111 86 109 81 106 76Z" />
          {teeth.map((x) => (
            <rect key={`t${x}`} className="xr__b" x={x} y="94" width="3" height="5" rx="1" />
          ))}
          {teeth.slice(0, 6).map((x) => (
            <rect key={`b${x}`} className="xr__b" x={x + 1.7} y="100" width="3" height="4.5" rx="1" />
          ))}
          <path className="xr__ln" d="M84 102C92 112 100 116 106 116C114 116 122 110 126 102" />
          {/* a hair bow, obviously */}
          <g className="xr-bow" style={pivot(128, 22)}>
            <path className="xr__bow" d="M128 22C120 12 110 12 112 22C110 32 120 32 128 22ZM128 22C136 12 146 12 144 22C146 32 136 32 128 22Z" />
            <circle className="xr__bow" cx="128" cy="22" r="3.2" />
            <path className="xr__bow" d="M126 25L122 36M130 25L134 36" />
          </g>
        </g>

        {/* the phone, faithfully x-rayed */}
        <rect className="xr__est" x="78" y="48" width="62" height="50" rx="7" />
        <circle className="xr__ln" cx="88" cy="58" r="4" />
        <circle className="xr__ln" cx="88" cy="70" r="4" />

        {/* raised arm holding the phone */}
        <g className="xr-armR" style={pivot(190, 160)}>
          {DOUBLE('M192 162L254 180', 8.5)}
          <circle className="xr__b xr__joint" cx="255" cy="181" r="6.5" />
          {DOUBLE('M253 177L182 84', 5.4)}
          {DOUBLE('M247 184L176 90', 4.2)}
          <path className="xr__b" d="M170 76C176 72 184 78 186 86L178 92C172 90 168 82 170 76Z" />
          {DOUBLE('M172 74L160 58M178 72L170 52M182 76L178 56M168 82L150 74', 2.8)}
          <circle className="xr__b" cx="160" cy="58" r="1.6" />
          <circle className="xr__b" cx="170" cy="52" r="1.6" />
          <circle className="xr__b" cx="178" cy="56" r="1.6" />
        </g>

        {/* hanging arm (sways) */}
        <g className="xr-armL" style={pivot(48, 172)}>
          {DOUBLE('M48 176L30 316', 8.5)}
          <circle className="xr__b xr__joint" cx="29" cy="320" r="6.5" />
          {DOUBLE('M31 324L37 404', 4.8)}
          {DOUBLE('M24 324L29 405', 3.8)}
          <path className="xr__b" d="M28 408C34 404 42 406 42 414L40 424C36 428 30 426 28 420Z" />
          {DOUBLE('M31 426L32 444M36 426L38 446M40 424L44 440', 2.6)}
          {/* scrunchie on the wrist */}
          <ellipse className="xr__bow" cx="33" cy="406" rx="9" ry="4" />
        </g>

        {/* pelvis */}
        <path className="xr__b" d="M70 392C66 368 88 360 108 374C116 381 128 381 136 374C156 360 182 364 184 388C186 405 172 420 150 424L104 424C84 420 72 408 70 392Z" />
        <path className="xr__ln" d="M112 384C118 398 126 398 132 384M100 410C110 416 140 416 152 410" />
        <circle className="xr__b xr__joint" cx="96" cy="416" r="7.5" />
        <circle className="xr__b xr__joint" cx="184" cy="416" r="7.5" />

        {/* legs, mostly hidden behind the strip */}
        {DOUBLE('M98 420L108 572', 9.5)}
        {DOUBLE('M182 420L190 572', 9.5)}
        <ellipse className="xr__b xr__joint" cx="108" cy="582" rx="8.5" ry="9.5" />
        <ellipse className="xr__b xr__joint" cx="190" cy="582" rx="8.5" ry="9.5" />
        {DOUBLE('M109 594L113 700', 7.5)}
        {DOUBLE('M100 596L102 700', 3.8)}
        {DOUBLE('M190 594L193 700', 7.5)}
        {DOUBLE('M200 596L203 700', 3.8)}

        {/* scan beam */}
        <rect className="xr-scan" x="-10" y="-60" width={person.cutoutW + 20} height="60" fill="url(#xr-scan)" />

        {/* twinkles */}
        {sparkles.map(([x, y, d]) => (
          <path key={`${x}-${y}`} className="xr-tw" style={{ ...pivot(x, y), animationDelay: `${d}s` }} d={`M${x} ${y - 6}L${x + 1.6} ${y - 1.6}L${x + 6} ${y}L${x + 1.6} ${y + 1.6}L${x} ${y + 6}L${x - 1.6} ${y + 1.6}L${x - 6} ${y}L${x - 1.6} ${y - 1.6}Z`} />
        ))}

        {/* labels */}
        <path className="xr__lead" d="M96 40L150 -6H300" />
        <circle className="xr__dot" cx="96" cy="40" r="2.4" />
        <path className="xr__lead" d="M126 44L170 22H300" />
        <circle className="xr__dot" cx="126" cy="44" r="2.4" />
        <path className="xr__lead" d="M131 60L190 50H300" />
        <circle className="xr__dot" cx="131" cy="60" r="2.4" />
        <path className="xr__lead" d="M90 202L40 214H-14" />
        <circle className="xr__dot" cx="90" cy="202" r="2.4" />
      </svg>
      {hero.xray.map(([b, t], i) => (
        <p className="xr__lab" key={b} style={{ left: '104%', top: `${[-4, 0.6, 5.2][i]}%` }}>
          <b>{b}</b>
          {t}
        </p>
      ))}
      <p className="xr__lab xr__lab--phone" style={{ right: '96%', top: '17%', left: 'auto', textAlign: 'right' }}>
        <b>phone</b>
        {hero.xrayPhone}
      </p>
      <p className="xr__lab xr__lab--heart" style={{ right: '104%', top: '28.5%', left: 'auto', textAlign: 'right' }}>
        <b>heart ♡</b>
        {hero.xrayHeart}
      </p>
      <p className="xr__tag" style={{ top: '40%', right: '100%' }}>
        {hero.xrayTag}
      </p>
    </div>
  );
}

function HeroLayer({ code }: { code?: boolean }) {
  return (
    <div
      className={`hx__layer hx__layer--${code ? 'code' : 'design'}`}
      {...(code ? { 'aria-hidden': true, inert: true } : { 'data-hx-design': '' })}
    >
      <div className="hx__bar">
        <p className="hx__file" data-spec="cwd · git:(main) · pushed on a friday">
          <span className="hx__file-d">
            <svg className="hx__file-ic" viewBox="0 0 16 16" aria-hidden="true">
              <path d="M5.5 1.5v13M10.5 1.5v13M1.5 5.5h13M1.5 10.5h13" />
            </svg>
            <span className="hx__file-dir">{hero.file.dir}</span>
            <button className="hx__file-name" type="button" data-file data-cursor="save">
              {hero.file.name}<b data-file-v>7</b>
              <small>{hero.file.ext}</small>
            </button>
            <svg className="hx__file-chev" viewBox="0 0 10 10" aria-hidden="true">
              <path d="M2.5 4 5 6.5 7.5 4" />
            </svg>
          </span>
          <span className="hx__file-c" aria-hidden="true">
            <i>~/</i>{hero.file.repo}{' '}
            <span>
              git:(<b>main</b>)
            </span>{' '}
            <em>✓</em>
          </span>
          {code && <Spec t="cwd · git:(main) · pushed on a friday" below />}
        </p>
        <p className="hx__status" data-spec="status · dot pulses every 2s">
          <i className="hx__dot" aria-hidden="true" />
          <a href={hero.statusHref} data-cursor="start">
            {hero.status} <span className="hx__sub">{hero.statusSub}</span>
          </a>
          {code && <Spec t="status · dot pulses every 2s" below />}
        </p>
        <p className="hx__clock" data-spec="time · Asia/Kolkata">
          {person.city} <time data-clock>10:00</time>
          {code && <Spec t="time · Asia/Kolkata" below />}
        </p>
      </div>

      <div className="hx__stage">
        <h1 className="hx__name" data-spec="" aria-label={person.name}>
          <Chars word={person.wordmark[0]} /> <Chars word={person.wordmark[1]} />
          {code && <Spec t="h1 · Geist 500 · fit-to-width · -0.066em" />}
        </h1>

        <figure className="hx__me">
          <span className="hx__cut">
            {code ? (
              <img className="hx__photo" src={person.cutout} alt="" width={person.cutoutW} height={person.cutoutH} />
            ) : (
              <span
                className="hx__photo ax"
                data-ax=""
                role="img"
                aria-label={hero.photoAlt}
                tabIndex={0}
                data-cursor="focus mode"
                dangerouslySetInnerHTML={{ __html: ASPIRANT }}
              />
            )}
          </span>
          {code && <XRay />}
          <figcaption className="hx__say" data-spec="chat bubble · back.out(1.7)">
            <span className="hx__typing" aria-hidden="true">
              <i />
              <i />
              <i />
            </span>
            <span className="hx__msg" data-say>
              {hero.bubble}
            </span>
            <time>9:41</time>
            {code && <Spec t="chat bubble · back.out(1.7)" />}
          </figcaption>
        </figure>

        <div className="hx__left">
          <p className="hx__role" data-spec="">
            {hero.roleLine1}
            <br />
            {hero.roleLine2Pre} <em>{hero.roleLine2Em}</em>.
            {code && <Spec t="p · Geist 500 · 40/1.02 · -0.045em" />}
          </p>
          <div className="hx__ctas" data-spec="flex · gap 10px">
            <a className="hx__btn hx__btn--ink" href={cta.diagnosticHref} target="_blank" rel="noopener" data-cursor="free">
              <span>{hero.ctaPrimary}</span>
              <small>{hero.ctaSmall}</small>
              <ArrowIcon />
            </a>
            <a className="hx__btn" href={hero.ctaScholarshipHref} target="_blank" rel="noopener" data-cursor="register">
              <span>{hero.ctaScholarship}</span>
              <TestIcon />
            </a>
            <p className="hx__call">
              <a href={hero.ctaSecondaryHref} data-cursor="₹1 trial">
                {hero.ctaSecondary}
              </a>
              <span> · {hero.ctaNote}</span>
            </p>
            {code && <Spec t="flex · gap 10px · h 80" below />}
          </div>
        </div>

        <div className="hx__right">
          <a className="hx__stamp" href="#receipts" data-stamp data-cursor="scroll" aria-label="Scroll to the receipts">
            <svg viewBox="0 0 120 120" aria-hidden="true">
              <defs>
                <path id={code ? 'stamp-ring-c' : 'stamp-ring'} d="M60 60m-45 0a45 45 0 1 1 90 0a45 45 0 1 1-90 0" />
              </defs>
              <text textLength={282} lengthAdjust="spacing">
                <textPath href={code ? '#stamp-ring-c' : '#stamp-ring'}>{hero.stamp}</textPath>
              </text>
            </svg>
            <span>
              <svg viewBox="0 0 16 16" aria-hidden="true">
                <path d="M8 2.5v11M3.5 9 8 13.5 12.5 9" />
              </svg>
            </span>
          </a>
          <p className="hx__lede" data-spec="">
            {hero.lede.pre}
            <b>{hero.lede.bold[0]}</b>, <b>{hero.lede.bold[1]}</b>, <b>{hero.lede.bold[2]}</b> and <b>{hero.lede.bold[3]}</b>
            {hero.lede.mid}
            <a className="stk stk--a" href="#p-mentor" data-cursor="mentor" aria-label="Personal mentor">
              <img src="/img/icons/mentor.svg" alt="" width={32} height={32} />
            </a>{' '}
            {hero.lede.a}
            <a className="stk stk--b" href="#p-parents" data-cursor="parents" aria-label="Parent dashboard">
              <img src="/img/icons/parent.svg" alt="" width={32} height={32} />
            </a>{' '}
            {hero.lede.b}
            <em>{hero.lede.em}</em>
            {code && <Spec t="p · Geist 400 · 19/1.58 · -0.012em" />}
          </p>
          <p className="hx__quip" data-spec="">
            {hero.quip[0]}
            <br />
            {hero.quip[1]}
            {code && <Spec t="p · Geist Mono 400 · 12/1.55 · 0.060em" below />}
          </p>
        </div>

        {!code && (
          <div className="hx__sparkles" aria-hidden="true">
            {SPARKLES.map(([x, y, size, d, ch], i) => (
              <i key={i} style={{ left: `${x}%`, top: `${y}%`, fontSize: size, animationDelay: `${d}s` }}>
                {ch}
              </i>
            ))}
          </div>
        )}
        {!code && (
          <>
            <div className="mp mp--client" aria-hidden="true">
              <svg viewBox="0 0 18 20">
                <path d="M1.6 1.6 16.2 9.4l-6.5 1.6-3.2 6.7z" />
              </svg>
              <p>
                <b>{hero.cursorNames.a}</b>
                <span />
              </p>
            </div>
            <div className="mp mp--mentor" aria-hidden="true">
              <svg viewBox="0 0 18 20">
                <path d="M1.6 1.6 16.2 9.4l-6.5 1.6-3.2 6.7z" />
              </svg>
              <p>
                <b>{hero.cursorNames.b}</b>
                <span />
              </p>
            </div>
          </>
        )}

        {code && (
          <div className="hx__notes">
            <div className="hx__guide" data-guide="cap">
              <span>cap height</span>
            </div>
            <div className="hx__guide" data-guide="x">
              <span>x-height</span>
            </div>
            <div className="hx__guide hx__guide--base" data-guide="base">
              <span>baseline</span>
            </div>
            <div className="hx__guide" data-guide="desc">
              <span>descender</span>
            </div>
            <div className="hx__rl hx__rl--h" data-rl="gutter">
              <b>0</b>
            </div>
            <div className="hx__rl hx__rl--h" data-rl="gap">
              <b>0</b>
            </div>
            <div className="hx__layers">
              <p>
                layers<span>⌥ 1</span>
              </p>
              <ul>
                <li style={{ paddingLeft: 12 }}><i>▾</i>header.hx</li>
                <li style={{ paddingLeft: 26 }}><i>T</i>h1 · {person.name}</li>
                <li style={{ paddingLeft: 26 }}><i>▾</i>figure.me</li>
                <li style={{ paddingLeft: 40 }}><i>▣</i>img · aspirant (selfie)</li>
                <li style={{ paddingLeft: 40 }}><i>✚</i>x-ray · 206 bones</li>
                <li style={{ paddingLeft: 40 }}><i>◯</i>bubble · excuses</li>
                <li className="is-sel" style={{ paddingLeft: 26 }}><i>▭</i>gap · 2px → 0px</li>
              </ul>
            </div>
          </div>
        )}
      </div>

      <div className="worked" aria-label="Built for">
        <p className="worked__label">
          <svg viewBox="0 0 24 24" aria-hidden="true">
            <path d="M21 15.5v-2l-8-5V3.6a1.5 1.5 0 0 0-3 0v4.9l-8 5v2l8-2.5v5.4l-2 1.5V21l3.5-1 3.5 1v-1.6l-2-1.5V13z" />
          </svg>
          <span>{hero.builtFor}</span>
        </p>
        <ul className="sr-only">
          {flipboard.map((f) => (
            <li key={f.name}>{f.name}</li>
          ))}
        </ul>
        <div className="fb" aria-hidden="true" data-fb>
          <span className="fb__no">
            {person.initials} <b data-fb-no>01</b>
          </span>
          <span className="fb__cells" data-fb-cells>
            {Array.from({ length: 14 }, (_, i) => (
              <span className="fb__c" key={i}>
                <i>{flipboard[0].name[i] && flipboard[0].name[i] !== ' ' ? flipboard[0].name[i] : ' '}</i>
              </span>
            ))}
          </span>
          <span className="fb__f fb__role">
            <span data-fb-role>{flipboard[0].role}</span>
          </span>
          <span className="fb__f fb__year">
            <span data-fb-year>{flipboard[0].year}</span>
          </span>
          <span className="fb__f fb__st">
            <span data-fb-st>
              <i />
              {flipboard[0].st}
            </span>
          </span>
        </div>
        <p className="worked__note" aria-hidden="true">
          {hero.gateNote[0]}<sup>*</sup>
          <small>*{hero.gateNote[1]}</small>
        </p>
      </div>
    </div>
  );
}

